def calculate_premium(policy_type, coverage_level, risk_factors, state, age_bracket, credit_tier):
    premium = 0

    # Base premium calculation
    base_premium = 1000 + (coverage_level * 50)

    # Risk factor adjustments
    if 'high_risk' in risk_factors:
        premium += 200
    elif 'medium_risk' in risk_factors:
        premium += 100

    # State-specific adjustments
    if state == 'California':
        premium += 300
    elif state == 'New York':
        premium += 400

    # Age bracket adjustments
    if age_bracket == 'senior':
        premium += 150
    elif age_bracket == 'middle_aged':
        premium += 75

    # Credit tier adjustments
    if credit_tier == 'good':
        premium -= 50
    elif credit_tier == 'fair':
        premium -= 25

    return premium
