import pandas as pd

def process_excel_files(directory):
    for file_name in os.listdir(directory):
        if file_name.endswith('.xlsx') or file_name.endswith('.xls'):
            file_path = os.path.join(directory, file_name)
            df = pd.read_excel(file_path)

            for sheet_name in df.sheet_names:
                sheet_df = df[sheet_name]

                for row_index, row in sheet_df.iterrows():
                    for cell_index, cell_value in enumerate(row):
                        # Apply transformation based on conditions
                        if cell_value > 10:
                            new_value = cell_value * 2
                        else:
                            new_value = cell_value + 5

                        # Update the cell value
                        sheet_df.at[row_index, cell_index] = new_value

            # Save the modified DataFrame back to an Excel file
            output_file_path = os.path.join(directory, f'processed_{file_name}')
            sheet_df.to_excel(output_file_path, index=False)

# Example usage
